void __fastcall RENDERER_D3D_SaveDeviceConfigToRegistry(uint32_t nRenderMode, int nDeviceIndex) {
    char szGuidKey[260];
    char szDeviceNameKey[260];
    char szFlagsKey[260];
    DWORD dwDisposition;
    sprintf(szDeviceNameKey, "DeviceName");
    sprintf(szFlagsKey, "dwFlags");
    sprintf(szGuidKey, "GUID");
    HKEY hCreatedKey = (HKEY)0x0;
    LSTATUS LVar1 = RegCreateKeyExA((HKEY)0x80000001, "SOFTWARE\\Blizzard Entertainment\\Diablo II\\VideoConfig", 0, (LPSTR)0x0, 0, 0x20006, (LPSECURITY_ATTRIBUTES)0x0, &hCreatedKey, &dwDisposition);
    HKEY hKey = hCreatedKey;
    if (LVar1) {
      return;
    }

    uint32_t dwRegValue = nRenderMode;
    /* BYTE * lpData for RegSetValueExA */ /* DWORD dwType for RegSetValueExA */ /* DWORD Reserved for RegSetValueExA */ /* LPCSTR lpValueName for RegSetValueExA */ /* HKEY hKey for RegSetValueExA */ RegSetValueExA(hCreatedKey, "Render", 0, 4, (uint8_t*)&dwRegValue, 4);
    char* lpData = gdwD3DDeviceFlags[nDeviceIndex].szName;
    if (!lpData) {
      CRT_ReturnValue(0x80004005);
    }

    int iVar2 = lstrlenA(lpData);
    /* DWORD cbData for RegSetValueExA */ /* BYTE * lpData for RegSetValueExA */ /* DWORD dwType for RegSetValueExA */ /* DWORD Reserved for RegSetValueExA */ /* LPCSTR lpValueName for RegSetValueExA */ /* HKEY hKey for RegSetValueExA */ RegSetValueExA(hKey, szDeviceNameKey, 0, 1, (uint8_t*)lpData, iVar2 + 1);
    dwRegValue = gdwD3DDeviceFlags[nDeviceIndex].dwFlags;
    /* DWORD cbData for RegSetValueExA */ /* BYTE * lpData for RegSetValueExA */ /* DWORD dwType for RegSetValueExA */ /* DWORD Reserved for RegSetValueExA */ /* LPCSTR lpValueName for RegSetValueExA */ /* HKEY hKey for RegSetValueExA */ RegSetValueExA(hKey, szFlagsKey, 0, 4, (uint8_t*)&dwRegValue, 4);
    /* DWORD cbData for RegSetValueExA */ /* BYTE * lpData for RegSetValueExA */ /* DWORD dwType for RegSetValueExA */ /* DWORD Reserved for RegSetValueExA */ /* LPCSTR lpValueName for RegSetValueExA */ /* HKEY hKey for RegSetValueExA */ RegSetValueExA(hKey, szGuidKey, 0, 3, (uint8_t*)&gdwD3DDeviceFlags[nDeviceIndex].guid, 0x10);
    if (!hKey) {
      return;
    }

    /* HKEY hKey for RegCloseKey */ RegCloseKey(hKey);
}

void __stdcall RENDERER_D3D_AllocateTextureCaches() {
    int nSmackerBase;
    int nGenericNodeBytes;
    int nGenericCacheEnd;
    uint32_t uSubtileCacheAlloc;
    g_nBytesPerPixel = 2;
    g_bSupportsTextureCachingInternal = 0;
    uint32_t uSmallCacheAlloc = g_nVideoMemoryTotal;
    if (!(gnD3DTextureCapFlags & 2) || 0xcfffff < g_nVideoMemoryTotal) {
      if (0x1ffffff < g_nVideoMemoryTotal) {
        uSmallCacheAlloc = 0x2000000;
      }
    } else {
      g_bSupportsTextureCachingInternal = 1;
      if (0x1ffffff < g_nVideoMemoryFree) {
        g_nVideoMemoryFree = 0x2000000;
      }
      if (g_nVideoMemoryTotal <= g_nVideoMemoryFree) {
        uSmallCacheAlloc = g_nVideoMemoryFree;
      }
    }
    if (!g_bPerspectiveMode) {
      gnTextureMemoryUsageBytes = 0;
      gnGlideSubtileCacheMemBytes = 0;
      nSmackerBase = RENDERER_D3D_CreateSmackerSurfaces(0);
      nGenericNodeBytes = RENDERER_D3D_InitializeTextureCachePool(gD3DGenericTextureCache, nSmackerBase, (uSmallCacheAlloc - nSmackerBase) * 0x46 / 100 + nSmackerBase, 0x100, 0x100);
      nGenericCacheEnd = gD3DGenericTextureCache[0].nMaxNodes * g_nBytesPerPixel;
      uSubtileCacheAlloc = (uint32_t)((uint64_t)((uSmallCacheAlloc - nSmackerBase) * 0x50) * 0x51eb851f >> 0x20);
    } else {
      uint32_t uVideoMemBudget;
      if (!(gnD3DTextureCapFlags & 0x40)) {
        gnD3DTextureCacheBlockSize = 0x100;
        gnD3DTextureCacheCount = 0x80;
      } else {
        gnD3DTextureCacheBlockSize = 0xa0;
        gnD3DTextureCacheCount = 0x50;
      }

      nSmackerBase = gnD3DTextureCacheCount * gnD3DTextureCacheBlockSize;
      uSubtileCacheAlloc = uSmallCacheAlloc >> 1;
      if (0x5fffff < uSubtileCacheAlloc) {
        uSubtileCacheAlloc = 0x600000;
      }

      uVideoMemBudget = uSmallCacheAlloc >> 3;
      if (0x2fffff < uVideoMemBudget) {
        uVideoMemBudget = 0x300000;
      }

      nGenericNodeBytes = RENDERER_D3D_InitializeFontSystem(0);
      gnTextureMemoryUsageBytes = uSubtileCacheAlloc;
      nSmackerBase = d3dFloorCache::D3DFLOOR_Initialize(&gD3DFloorTextureCache, nGenericNodeBytes, uSubtileCacheAlloc + nGenericNodeBytes, nSmackerBase * 2);
      gnGlideSubtileCacheMemBytes = uVideoMemBudget;
      nSmackerBase = d3dSubtileCache::D3DSUBTILE_Initialize(&gD3DSubtileTextureCache, nSmackerBase, uVideoMemBudget + nSmackerBase, 0x800);
      nGenericNodeBytes = RENDERER_D3D_InitializeTextureCachePool(gD3DGenericTextureCache, nSmackerBase, (uSmallCacheAlloc - nSmackerBase) * 0x14 / 100 + nSmackerBase, 0x100, 0x100);
      nGenericCacheEnd = gD3DGenericTextureCache[0].nMaxNodes * g_nBytesPerPixel;
      uSubtileCacheAlloc = (uint32_t)((uint64_t)((uSmallCacheAlloc - nSmackerBase) * 0x4b) * 0x51eb851f >> 0x20);
    }

    gnGlideSmallTextureCacheMemBytes = nGenericCacheEnd * 0x10000;
    nSmackerBase = RENDERER_D3D_InitializeTextureCachePool(gD3DGenericTextureCache + 1, nGenericNodeBytes, (uSubtileCacheAlloc >> 5) + nSmackerBase, 0x80, 0x80);
    gnGlideMediumTextureCacheMemBytes = gD3DGenericTextureCache[1].nMaxNodes * g_nBytesPerPixel * 0x4000;
    RENDERER_D3D_InitializeTextureCachePool(gD3DGenericTextureCache + 2, nSmackerBase, uSmallCacheAlloc, 0x20, 0x20);
    gnGlideLargeTextureCacheMemBytes = gD3DGenericTextureCache[2].nMaxNodes * g_nBytesPerPixel * 0x400;
    RENDERER_D3D_InitializeTexturePools();
    D2CMP::SRC::CelCmp::GFX_SetSpriteCacheMaxSize((size_t)(uintptr_t)d3dFloorCache::D3D_InvalidateTileCachesForEntry);
}

void __stdcall RENDERER_D3D_FreeTextureCaches() {
    if (!g_bPerspectiveMode) {
      RENDERER_D3D_ReleaseSmackerSurfaces();
    } else {
      RENDERER_D3D_ReleaseFontTextures();
      d3dFloorCache::D3DFLOOR_Free(&gD3DFloorTextureCache, 1);
      d3dSubtileCache::D3DSUBTILE_Free(&gD3DSubtileTextureCache, 1);
    }

    d3dTextureCache::D3DTEXCACHE_Free(gD3DGenericTextureCache, 1);
    d3dTextureCache::D3DTEXCACHE_Free(gD3DGenericTextureCache + 1, 1);
    d3dTextureCache::D3DTEXCACHE_Free(gD3DGenericTextureCache + 2, 1);
    RENDERER_D3D_ReleaseTexturePools();
}

void __stdcall RENDERER_D3D_ReleaseDevice() {
    // Static local variables (originally global data)
    static IDirectDrawSurface7 * g_pD3DSurfacePrimary;

    if (!g_bDeviceInitialized) {
      return;
    }

    RENDERER_D3D_ReleaseGroundTileCache();
    d3dFloorCache::D3D_FreeSystemMemoryTexturesForTiles();
    RENDERER_D3D_FreeTextureCaches();
    if (g_pD3DViewport) {
      g_pD3DViewport->lpVtbl->Release(g_pD3DViewport);
      g_pD3DViewport = 0;
    }
    if (g_pD3DDevice) {
      g_pD3DDevice->lpVtbl->Release(g_pD3DDevice);
      g_pD3DDevice = 0;
    }
    if (g_pDDGammaControl) {
      DWORD nResult;
      nResult = g_pDDGammaControl->lpVtbl->SetGammaRamp(g_pDDGammaControl, 0, g_OriginalGammaRamp);
      if (nResult && nResult != 0x887601c2) {
        DIRECTD3D_LogError("Failed to restore original gamma ramp", nResult);
      }

      g_pDDGammaControl->lpVtbl->Release(g_pDDGammaControl);
      g_pDDGammaControl = 0;
    }
    if (g_pD3DSurfacePrimary) {
      g_pD3DSurfacePrimary->lpVtbl->Release(g_pD3DSurfacePrimary);
      g_pD3DSurfacePrimary = 0;
    }
    if (D3DSurfaceSecondary) {
      D3DSurfaceSecondary->lpVtbl->Release(D3DSurfaceSecondary);
      D3DSurfaceSecondary = 0;
    }
    if (g_pD3DSurfaceBackbuffer) {
      g_pD3DSurfaceBackbuffer->lpVtbl->Release(g_pD3DSurfaceBackbuffer);
      g_pD3DSurfaceBackbuffer = 0;
    }

    g_bDeviceInitialized = 0;
    g_bCutsceneModeActive = 0;
}

BOOL __stdcall RENDERER_D3D_DestroyWindow() {
    RENDERER_D3D_ReleaseDevice();
    gnGlideWindowHandle = 0;
    return 1;
}

BOOL __stdcall RENDERER_D3D_InitializeCutsceneMode() {
    char* szErrorMessage;
    DDSURFACEDESC2 dwDDSurfDescSize;
    if (g_bDeviceInitialized) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x7cb);
      exit(-1);
    }

    RENDERER_nWindowWidth = 0x280;
    RENDERER_nWindowHeight = 0x1e0;
    uint32_t nBitsPerPixel = 0x10;
    if (!(gnD3DTextureCapFlags & 0x80)) {
      if (gnD3DTextureCapFlags & 0x100) {
        nBitsPerPixel = 0x18;
      }
    } else {
      nBitsPerPixel = 0x20;
    }

    DWORD nSetDisplayModeResult = g_pDirectDraw7->lpVtbl->SetDisplayMode(g_pDirectDraw7, 0x280, 0x1e0, nBitsPerPixel, 0, 0);
    if (!nSetDisplayModeResult) {
      dwDDSurfDescSize.dwSize = 0x7c;
      memset(&dwDDSurfDescSize.dwFlags, 0, 0x78);
      dwDDSurfDescSize.dwFlags = 1;
      dwDDSurfDescSize.dwCaps = 0x4200;
      nSetDisplayModeResult = g_pDirectDraw7->lpVtbl->CreateSurface(g_pDirectDraw7, &dwDDSurfDescSize, (void**)&g_pD3DSurfaceBackbuffer, nullptr);
      if (!nSetDisplayModeResult) {
        g_bDeviceInitialized = 1;
        g_bCutsceneModeActive = 1;
        return 1;
      }

      szErrorMessage = "Failed to create primary surface for cutscenes";
    } else {
      szErrorMessage = "SetDisplayMode failed!";
    }

    DIRECTD3D_LogError(szErrorMessage, nSetDisplayModeResult);
    Fog::Src::LogManager::LOGFILE_WriteStringToFile("Opening Direct3D window for cutscenes failed!");
    return 0;
}

BOOL __stdcall BeginCutScene() {
    if (gnRenderState) {
      return 0;
    }
    if (!(gnD3DTextureCapFlags & 0x80) && !(gnD3DTextureCapFlags & 0x100)) {
      return 1;
    }

    RENDERER_D3D_ReleaseDevice();
    BOOL BVar1 = RENDERER_D3D_InitializeCutsceneMode();
    return BVar1;
}

void __fastcall SetGamma(int nGamma) {
    int nEntryCount;
    uint32_t aGammaRampRed[128];
    uint32_t aGammaRampGreen[128];
    uint32_t aGammaRampBlue[128];
    if (!(gnD3DTextureCapFlags & 0x10)) {
      return;
    }

    Fog::Src::DataArrays::FOG_FillArrayWithRandomInts(nGamma, aGammaRampRed, (double)BOOL_0074c020, (uint32_t*)0x2, 0x100, 0xffff);
    uint32_t* pGammaRampRedSrc = aGammaRampRed;
    uint32_t* pGammaRampGreenDst = aGammaRampGreen;
    for (nEntryCount = 0x80; nEntryCount; nEntryCount--) {
      *pGammaRampGreenDst = *pGammaRampRedSrc;
      pGammaRampRedSrc++;
      pGammaRampGreenDst++;
    }

    uint32_t* pGammaRampDst = aGammaRampRed;
    uint32_t* pGammaRampSrc = aGammaRampBlue;
    for (nEntryCount = 0x80; nEntryCount; nEntryCount--) {
      *pGammaRampSrc = *pGammaRampDst;
      pGammaRampDst++;
      pGammaRampSrc++;
    }

    if (!g_pDDGammaControl) {
      return;
    }

    DWORD nResult = g_pDDGammaControl->lpVtbl->SetGammaRamp(g_pDDGammaControl, 0, aGammaRampRed);
    if (!nResult) {
      return;
    }

    DIRECTD3D_LogError("Failed to set gamma ramp", nResult);
}

BOOL __fastcall GetBackBuffer(BYTE * pBuffer) {
    int nWidthSave;
    uint32_t* puSurfPixel;
    int nPixelIdx;
    DDSURFACEDESC2 ddSurfDescSize;
    uint32_t* pRowStart;
    int nRow;
    uint32_t uPixel32;
    ddSurfDescSize.dwSize = 0x7c;
    memset(&ddSurfDescSize.dwFlags, 0, 0x78);
    if (!D3DSurfaceSecondary) {
      return 0;
    }

    DWORD DVar1 = D3DSurfaceSecondary->lpVtbl->Lock(D3DSurfaceSecondary, nullptr, &ddSurfDescSize, 0x11, nullptr);
    if (!DVar1) {
      uint8_t* pOutByte;
      nRow = 0;
      nWidthSave = RENDERER_nWindowWidth;
      if (0 < RENDERER_nWindowHeight) {
        do {
          nPixelIdx = 0;
          pOutByte = pBuffer;
          puSurfPixel = (uint32_t*)ddSurfDescSize.lpSurface;
          if (0 < nWidthSave) {
            do {
              uPixel32 = *puSurfPixel;
              *pOutByte = (uint8_t)(uPixel32 >> 0x10);
              pOutByte[1] = (uint8_t)(uPixel32 >> 8);
              pOutByte[2] = (uint8_t)uPixel32;
              nPixelIdx++;
              pOutByte += 3;
              nWidthSave = RENDERER_nWindowWidth;
              puSurfPixel++;
            } while (nPixelIdx < RENDERER_nWindowWidth);
          }

          ddSurfDescSize.lpSurface = (void*)((int)ddSurfDescSize.lpSurface + ((int)(ddSurfDescSize.lPitch + (ddSurfDescSize.lPitch >> 0x1f & 3U)) >> 2) * 4);
          nRow++;
          pBuffer += nWidthSave * 3;
        } while (nRow < RENDERER_nWindowHeight);
      }

      DVar1 = D3DSurfaceSecondary->lpVtbl->Unlock(D3DSurfaceSecondary, nullptr);
      if (!DVar1) {
        return 1;
      }

      DIRECTD3D_LogError("Unlock failed!", DVar1);
      return 0;
    }

    DIRECTD3D_LogError("Lock failed!", DVar1);
    return 0;
}

int32_t __fastcall RENDERER_D3D_CreateSystemMemoryTexture(IDirectDrawSurface7 * * ppSurface, IDirect3DTexture2 * * ppTexture, int32_t nWidth, int32_t nHeight) {
    int nCopyCount;
    DDSURFACEDESC2 ddSurfaceDesc;
    ddSurfaceDesc.dwSize = 0x7c;
    memset(&ddSurfaceDesc.dwFlags, 0, 0x78);
    ddSurfaceDesc.dwFlags = 0x1007;
    ddSurfaceDesc.dwCaps = 0x840;
    DWORD* pSrcTemplate = (DWORD*)&gsD3DTextureDescTemplate;
    DWORD* pDstPixelFormat = ddSurfaceDesc.ddpfPixelFormat;
    for (nCopyCount = 8; nCopyCount; nCopyCount--) {
      *pDstPixelFormat = *pSrcTemplate;
      pSrcTemplate++;
      pDstPixelFormat++;
    }

    ddSurfaceDesc.dwHeight = nHeight;
    ddSurfaceDesc.dwWidth = nWidth;
    DWORD dwResult = g_pDirectDraw7->lpVtbl->CreateSurface(g_pDirectDraw7, &ddSurfaceDesc, (void**)ppSurface, nullptr);
    if (dwResult) {
      DIRECTD3D_LogError("CreateSurface (memory surface)", dwResult);
      return 0;
    }

    dwResult = (*ppSurface)->lpVtbl->QueryInterface(*ppSurface, (GUID*)&gIID_IDirect3DSurface, (void**)ppTexture);
    if (!dwResult) {
      return 1;
    }

    DIRECTD3D_LogError("Failed to get texture interface for memory surface", dwResult);
    (*ppSurface)->lpVtbl->Release(*ppSurface);
    return 0;
}

void __stdcall RENDERER_D3D_ClearBackbuffer() {
    DDSURFACEDESC2 ddSurfDescSize;
    IDirectDrawSurface7* pTargetSurface = g_pD3DSurfaceBackbuffer;
    if (D3DSurfaceSecondary) {
      pTargetSurface = D3DSurfaceSecondary;
    }

    ddSurfDescSize.dwSize = 0x7c;
    memset(&ddSurfDescSize.dwFlags, 0, 0x78);
    DWORD nResult = pTargetSurface->lpVtbl->Lock(pTargetSurface, nullptr, &ddSurfDescSize, 0x21, nullptr);
    int nRowsLeft = RENDERER_nWindowHeight;
    if (nResult) {
      DIRECTD3D_LogError("Failed to lock render surface for clear", nResult);
      return;
    }

    for (; nRowsLeft; nRowsLeft--) {
      memset(ddSurfDescSize.lpSurface, 0, ddSurfDescSize.lPitch);
      ddSurfDescSize.lpSurface = (void*)((int)ddSurfDescSize.lpSurface + ddSurfDescSize.lPitch);
    }

    pTargetSurface->lpVtbl->Unlock(pTargetSurface, nullptr);
}

void __fastcall RENDERER_D3D_CopySurfacePixels(IDirectDrawSurface7 * pSrcSurface, IDirectDrawSurface7 * pDestSurface, int nHeight) {
    DDSURFACEDESC2 ddDestDescSize;
    size_t nCopyWidth;
    void* pDestRowCopy;
    void* pSrcRowCopy;
    ddDestDescSize.dwSize = 0x7c;
    memset(&ddDestDescSize.dwFlags, 0, 0x78);
    DWORD nLockResult = pDestSurface->lpVtbl->Lock(pDestSurface, nullptr, &ddDestDescSize, 0x21, nullptr);
    if (!nLockResult) {
      DDSURFACEDESC2 ddSrcDescSize;
      ddSrcDescSize.dwSize = 0x7c;
      memset(&ddSrcDescSize.dwFlags, 0, 0x78);
      nLockResult = pSrcSurface->lpVtbl->Lock(pSrcSurface, nullptr, &ddSrcDescSize, 0x21, nullptr);
      if (!nLockResult) {
        nCopyWidth = ddDestDescSize.lPitch;
        pSrcRowCopy = ddSrcDescSize.lpSurface;
        pDestRowCopy = ddDestDescSize.lpSurface;
        if ((uint32_t)ddSrcDescSize.lPitch <= (uint32_t)ddDestDescSize.lPitch) {
          nCopyWidth = ddSrcDescSize.lPitch;
        }

        for (; nHeight; nHeight--) {
          memcpy(pSrcRowCopy, pDestRowCopy, nCopyWidth);
          pSrcRowCopy = (void*)((int)pSrcRowCopy + ddSrcDescSize.lPitch);
          pDestRowCopy = (void*)((int)pDestRowCopy + ddDestDescSize.lPitch);
        }
      } else {
        DIRECTD3D_LogError("Failed to lock dest surface", nLockResult);
      }
    } else {
      DIRECTD3D_LogError("Failed to lock source surface", nLockResult);
    }

    pDestSurface->lpVtbl->Unlock(pDestSurface, nullptr);
    pSrcSurface->lpVtbl->Unlock(pSrcSurface, nullptr);
}

